CREATE VIEW app_threads AS SELECT t.* FROM thread t JOIN process p USING(upid) WHERE p.name='com.bargeboss.game';
CREATE VIEW app_slices AS SELECT s.*,t.name AS thread_name FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN app_threads t USING(utid) WHERE s.dur>0;
SELECT CASE WHEN name GLOB 'BB draw*' THEN 'BB draw' WHEN name GLOB 'DrawFrames *' THEN 'DrawFrames' WHEN name GLOB 'Texture upload*' THEN 'Texture upload' ELSE name END AS label,count(*) n,round(percentile(dur,50)/1e6,3) p50_ms,round(percentile(dur,95)/1e6,3) p95_ms,round(max(dur)/1e6,3) max_ms FROM app_slices WHERE name GLOB 'BB draw*' OR name GLOB 'DrawFrames *' OR name IN ('flush commands','postAndWait','dequeueBuffer','waitForBufferRelease','QueueSubmit') OR name GLOB 'Texture upload*' GROUP BY label;
SELECT t.name,count(*) n,min(c.value) minimum,max(c.value) maximum,percentile(c.value,50) median,percentile(c.value,95) p95 FROM counter c JOIN track t ON t.id=c.track_id WHERE t.name GLOB '*gpu_duration*' OR t.name='Reported gpu duration' GROUP BY t.name;
SELECT jank_type,present_type,count(*) n FROM actual_frame_timeline_slice WHERE upid=(SELECT upid FROM process WHERE name='com.bargeboss.game') GROUP BY jank_type,present_type ORDER BY n DESC;
